#!/usr/bin/env python3
"""Validate the commitment ledger.

Checks the schema plus the method rules from SPEC.md that a plain JSON-Schema
check cannot express. Standard library only, so it runs anywhere.

    python validate.py [commitments.json]

Exit code 0 if clean, 1 if any entry fails.
"""

from __future__ import annotations

import datetime as dt
import json
import pathlib
import re
import sys

HERE = pathlib.Path(__file__).parent

REQUIRED = [
    "id", "organisation", "org_type", "summary", "quote",
    "source_url", "source_title", "source_date", "accessed",
    "status", "verified_by",
]
ORG_TYPES = {"developer", "government", "standards_body", "other"}
STATUSES = {"open", "kept", "lapsed", "broken", "superseded", "unclear"}
ID_RE = re.compile(r"^HT-\d{4}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")

# Words that signal the summary has drifted from record-keeping into commentary.
EDITORIAL = [
    "egregious", "blatant", "cynical", "obviously", "clearly intended",
    "misleading", "deceptive", "hypocritical", "shameful", "pr stunt",
]


def _date_ok(value: str) -> bool:
    if not isinstance(value, str) or not DATE_RE.match(value):
        return False
    try:
        dt.date.fromisoformat(value)
    except ValueError:
        return False
    return True


def check_entry(entry: dict, seen_ids: set[str]) -> list[str]:
    problems: list[str] = []
    eid = entry.get("id", "<no id>")

    def bad(msg: str) -> None:
        problems.append(f"{eid}: {msg}")

    for field in REQUIRED:
        if not entry.get(field):
            bad(f"missing required field '{field}'")

    if "id" in entry:
        if not ID_RE.match(str(entry["id"])):
            bad("id must look like HT-0001")
        if entry["id"] in seen_ids:
            bad("duplicate id — ids are never reused")
        seen_ids.add(entry["id"])

    if entry.get("org_type") and entry["org_type"] not in ORG_TYPES:
        bad(f"org_type '{entry['org_type']}' not one of {sorted(ORG_TYPES)}")

    status = entry.get("status")
    if status and status not in STATUSES:
        bad(f"status '{status}' not one of {sorted(STATUSES)}")

    for field in ("source_date", "accessed", "due"):
        if entry.get(field) and not _date_ok(entry[field]):
            bad(f"{field} must be an ISO date (YYYY-MM-DD)")

    # Rule 1: no entry without a real verbatim quote.
    quote = entry.get("quote", "")
    if quote and len(quote.split()) < 5:
        bad("quote is too short to be a meaningful verbatim excerpt")
    if quote and quote.strip().startswith(("paraphrase", "roughly", "approx")):
        bad("quote field must be verbatim, not a paraphrase")

    # Rule: primary sources only — a secondary report is not admissible.
    url = (entry.get("source_url") or "").lower()
    if url and any(h in url for h in ("news.google", "/amp/", "medium.com/@")):
        bad("source_url looks like a secondary report; cite the primary document")

    # Rule 2: right of reply is mandatory before publishing 'broken'.
    if status == "broken":
        reply = entry.get("right_of_reply")
        if not isinstance(reply, dict) or not reply.get("notified_on"):
            bad("status 'broken' requires right_of_reply.notified_on")
        elif _date_ok(reply["notified_on"]):
            notified = dt.date.fromisoformat(reply["notified_on"])
            elapsed = (dt.date.today() - notified).days
            answered = reply.get("response_received") or reply.get("no_response")
            if elapsed < 14 and not answered:
                bad(
                    f"status 'broken' published {elapsed} days after notice; "
                    "the 14-day right-of-reply window has not closed"
                )

    # Rule: a status claim needs evidence behind it.
    if status in {"kept", "lapsed", "broken"} and not entry.get("status_evidence"):
        bad(f"status '{status}' asserted with no status_evidence")

    if status == "superseded" and not entry.get("supersedes"):
        bad("status 'superseded' requires a link to the superseding entry id")

    # Rule 4: record what was said, not why.
    summary = (entry.get("summary") or "").lower()
    for word in EDITORIAL:
        if word in summary:
            bad(f"summary contains editorial language ('{word}') — state the facts only")

    # Freshness: a stale access date means the claim has not been rechecked.
    if entry.get("accessed") and _date_ok(entry["accessed"]):
        age = (dt.date.today() - dt.date.fromisoformat(entry["accessed"])).days
        if age > 365:
            bad(f"last verified {age} days ago; re-check against the live source")

    if not entry.get("archive_url"):
        bad("no archive_url — primary sources move and disappear")

    return problems


def main(argv: list[str]) -> int:
    path = pathlib.Path(argv[1]) if len(argv) > 1 else HERE / "commitments.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        print(f"no ledger at {path}", file=sys.stderr)
        return 1
    except json.JSONDecodeError as exc:
        print(f"ledger is not valid JSON: {exc}", file=sys.stderr)
        return 1

    entries = data.get("entries", [])
    problems: list[str] = []
    seen_ids: set[str] = set()
    for entry in entries:
        problems.extend(check_entry(entry, seen_ids))

    if problems:
        print(f"{len(problems)} problem(s) in {len(entries)} entr(ies):\n")
        for problem in problems:
            print("  -", problem)
        return 1

    if not entries:
        print("Ledger is valid and empty. 0 entries. Nothing has been claimed yet.")
    else:
        counts: dict[str, int] = {}
        for entry in entries:
            counts[entry["status"]] = counts.get(entry["status"], 0) + 1
        summary = ", ".join(f"{k}: {v}" for k, v in sorted(counts.items()))
        print(f"Ledger is valid. {len(entries)} entries ({summary}).")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
